pub fn door_step(d: &Door, p: &Pending, now: u64, driver: bool) -> (Door, DoorOut) {
    let mut o = NOTHING;
    let mut last = d.last;
    let mut timeout = d.timeout;
    let entering = !same(d.last, d.state);
    let state = match d.state {
        DoorState::Idle | DoorState::Opened | DoorState::Closed => {
            if entering {
                last = d.state;
                o.pulley = Some(PulleyCommand::Stop);
            }
            match p.cmd {
                Some(c) => {
                    o.take_cmd = true;
                    let open = is_open(c);
                    match d.state {
                        // F2: no movement without the driver.
                        _ if !driver => d.state,
                        DoorState::Idle => {
                            if open { DoorState::Opening } else { DoorState::Closing }
                        }
                        DoorState::Opened => {
                            if open { DoorState::Opened } else { DoorState::Closing }
                        }
                        _ => {
                            if open { DoorState::Opening } else { DoorState::Closed }
                        }
                    }
                }
                None => d.state,
            }
        }
        DoorState::Opening | DoorState::Closing => {
            let opening = match d.state {
                DoorState::Opening => true,
                _ => false,
            };
            let mut stale = false;
            if entering {
                last = d.state;
                o.pulley = Some(if opening { PulleyCommand::RampUpCCW } else { PulleyCommand::RampUpCW });
                timeout = now.saturating_add(DOOR_TIMEOUT_MS);
                // F1: a flag raised before this movement started is not
                // this movement's overcurrent.
                if p.overcurrent {
                    o.take_overcurrent = true;
                    stale = true;
                }
            }
            let limit = if opening { p.open_limit } else { p.close_limit };
            match limit {
                Some(hit) => {
                    if opening {
                        o.take_open_limit = true;
                    } else {
                        o.take_close_limit = true;
                    }
                    if hit {
                        if opening { DoorState::Opened } else { DoorState::Closed }
                    } else {
                        d.state
                    }
                }
                None => match p.cmd {
                    Some(c) => {
                        o.take_cmd = true;
                        let open = is_open(c);
                        if opening && !open {
                            DoorState::Closing
                        } else if !opening && open {
                            DoorState::Opening
                        } else {
                            d.state
                        }
                    }
                    None => {
                        if p.overcurrent && !stale {
                            o.take_overcurrent = true;
                            // Opening stops; closing reverses (upstream).
                            if opening { DoorState::Idle } else { DoorState::Opening }
                        } else if now >= timeout {
                            DoorState::Idle
                        } else {
                            d.state
                        }
                    }
                },
            }
        }
    };
    (Door { state, last, timeout }, o)
}

