fn same(a: DoorState, b: DoorState) -> bool {
    match (a, b) {
        (DoorState::Idle, DoorState::Idle) => true,
        (DoorState::Opening, DoorState::Opening) => true,
        (DoorState::Opened, DoorState::Opened) => true,
        (DoorState::Closing, DoorState::Closing) => true,
        (DoorState::Closed, DoorState::Closed) => true,
        _ => false,
    }
}

