pub fn pulley_step(p: &Pulley, cmd: Option<PulleyCommand>) -> (Pulley, Option<Duty>) {
    let Pulley { state, dest, duty } = *p;
    match state {
        PulleyState::Hold => {
            let set = Some(Duty { a: 0, b: 0 });
            match cmd {
                Some(PulleyCommand::RampUpCCW) => {
                    (Pulley { state: PulleyState::RampingUpCCW, dest: PulleyState::RampingUpCCW, duty: 0 }, set)
                }
                Some(PulleyCommand::RampUpCW) => {
                    (Pulley { state: PulleyState::RampingUpCW, dest: PulleyState::RampingUpCW, duty: 0 }, set)
                }
                // F3: a stop in Hold cancels a pending reversal.
                Some(PulleyCommand::Stop) => (Pulley { state, dest: PulleyState::Hold, duty }, set),
                None => match dest {
                    PulleyState::RampingUpCCW => (Pulley { state: PulleyState::RampingUpCCW, dest, duty: 0 }, set),
                    PulleyState::RampingUpCW => (Pulley { state: PulleyState::RampingUpCW, dest, duty: 0 }, set),
                    _ => (*p, set),
                },
            }
        }
        PulleyState::RampingUpCCW | PulleyState::DrivingCCW => match cmd {
            Some(PulleyCommand::RampUpCW) => {
                (Pulley { state: PulleyState::RampingDownCCW, dest: PulleyState::RampingUpCW, duty }, None)
            }
            Some(PulleyCommand::Stop) => (Pulley { state: PulleyState::RampingDownCCW, dest: PulleyState::Hold, duty }, None),
            Some(PulleyCommand::RampUpCCW) => (*p, None),
            None => match state {
                PulleyState::RampingUpCCW => {
                    if duty < PULLEY_DUTY_MAX {
                        let duty = duty + 1;
                        (Pulley { state, dest, duty }, Some(Duty { a: duty, b: 0 }))
                    } else {
                        (Pulley { state: PulleyState::DrivingCCW, dest: PulleyState::DrivingCCW, duty }, None)
                    }
                }
                _ => (*p, Some(Duty { a: PULLEY_DUTY_MAX, b: 0 })),
            },
        },
        PulleyState::RampingUpCW | PulleyState::DrivingCW => match cmd {
            Some(PulleyCommand::RampUpCCW) => {
                (Pulley { state: PulleyState::RampingDownCW, dest: PulleyState::RampingUpCCW, duty }, None)
            }
            Some(PulleyCommand::Stop) => (Pulley { state: PulleyState::RampingDownCW, dest: PulleyState::Hold, duty }, None),
            Some(PulleyCommand::RampUpCW) => (*p, None),
            None => match state {
                PulleyState::RampingUpCW => {
                    if duty < PULLEY_DUTY_MAX {
                        let duty = duty + 1;
                        (Pulley { state, dest, duty }, Some(Duty { a: 0, b: duty }))
                    } else {
                        (Pulley { state: PulleyState::DrivingCW, dest: PulleyState::DrivingCW, duty }, None)
                    }
                }
                _ => (*p, Some(Duty { a: 0, b: PULLEY_DUTY_MAX })),
            },
        },
        PulleyState::RampingDownCCW => match cmd {
            Some(PulleyCommand::RampUpCCW) => {
                (Pulley { state: PulleyState::RampingUpCCW, dest: PulleyState::RampingUpCCW, duty }, None)
            }
            // F3: a stop while ramping down is kept.
            Some(PulleyCommand::Stop) => (Pulley { state, dest: PulleyState::Hold, duty }, None),
            Some(PulleyCommand::RampUpCW) => (Pulley { state, dest: PulleyState::RampingUpCW, duty }, None),
            None => {
                if duty > 0 {
                    let duty = duty - 1;
                    (Pulley { state, dest, duty }, Some(Duty { a: duty, b: 0 }))
                } else {
                    (Pulley { state: PulleyState::Hold, dest, duty }, None)
                }
            }
        },
        PulleyState::RampingDownCW => match cmd {
            Some(PulleyCommand::RampUpCW) => {
                (Pulley { state: PulleyState::RampingUpCW, dest: PulleyState::RampingUpCW, duty }, None)
            }
            // F3: a stop while ramping down is kept.
            Some(PulleyCommand::Stop) => (Pulley { state, dest: PulleyState::Hold, duty }, None),
            Some(PulleyCommand::RampUpCCW) => (Pulley { state, dest: PulleyState::RampingUpCCW, duty }, None),
            None => {
                if duty > 0 {
                    let duty = duty - 1;
                    (Pulley { state, dest, duty }, Some(Duty { a: 0, b: duty }))
                } else {
                    (Pulley { state: PulleyState::Hold, dest, duty }, None)
                }
            }
        },
    }
}

